package com.termux.app.workspace;
import android.app.Application;import android.os.Looper;import android.view.*;import android.widget.*;import com.termux.app.TermuxActivity;import com.termux.R;import com.termux.view.TerminalView;import java.lang.reflect.*;import java.util.*;import java.util.concurrent.atomic.*;import org.json.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.Config;import static org.junit.Assert.*;
/** Replays actual isolated native snapshots through the Android controller; never resends them. */
@RunWith(RobolectricTestRunner.class) @Config(sdk=28,application=Application.class)
public class ClaudeClarificationReplayTest {
 TermuxActivity activity;AgentChatUi ui;AgentChatView chat;WorkspaceStore.Session profile;JSONArray stages;AtomicReference<JSONObject> response=new AtomicReference<>();AtomicInteger requests=new AtomicInteger();
 @Before public void setup()throws Exception{
  // This headless replay verifies delivery/order, not display-frame timing (covered by AgentTextRevealTest).
  animationScale(0f);
  String text=new String(getClass().getResourceAsStream("/claude-clarification-native.json").readAllBytes(),java.nio.charset.StandardCharsets.UTF_8);stages=new JSONObject(text).getJSONArray("stages");activity=Robolectric.buildActivity(TermuxActivity.class).get();activity.setTheme(R.style.Theme_Termux_Black);WorkspaceLanguage.select(activity,"ru");FrameLayout host=new FrameLayout(activity);host.setId(R.id.workspace_terminal_surface);TerminalView terminal=new TerminalView(activity,null);host.addView(terminal);Field f=TermuxActivity.class.getDeclaredField("mTerminalView");f.setAccessible(true);f.set(activity,terminal);com.termux.shared.terminal.io.extrakeys.ExtraKeysView keys=new com.termux.shared.terminal.io.extrakeys.ExtraKeysView(activity,null);host.addView(keys);activity.setExtraKeysView(keys);keys.setVisibility(View.GONE);activity.setContentView(host);profile=new WorkspaceStore.Session();profile.claudeAgent=true;profile.environment="ubuntu";profile.claudeThread=stages.getJSONObject(0).getJSONObject("snapshot").getString("session");
 }
 @After public void finish()throws Exception{if(ui!=null)ui.close();activity.finish();animationScale(1f);}
 void animationScale(float value)throws Exception{Method m=android.animation.ValueAnimator.class.getDeclaredMethod("setDurationScale",float.class);m.setAccessible(true);m.invoke(null,value);}
 JSONObject snapshot(String label)throws Exception{for(int i=0;i<stages.length();i++)if(stages.getJSONObject(i).getString("label").equals(label))return stages.getJSONObject(i).getJSONObject("snapshot");throw new AssertionError(label);}
 void open(){ui=new AgentChatUi(activity,()->profile,()->true,(p,q)->{assertEquals("Only bounded local history snapshots", "chat-snapshot",q.getString("op"));requests.incrementAndGet();return new JSONObject(response.get().toString());});ui.sync();chat=org.robolectric.util.ReflectionHelpers.getField(ui,"view");}
 void apply(String label)throws Exception{response.set(snapshot(label));int count=requests.get();if(ui==null)open();else{Method m=AgentChatUi.class.getDeclaredMethod("retryConnection");m.setAccessible(true);m.invoke(ui);}for(int i=0;i<120;i++){Shadows.shadowOf(Looper.getMainLooper()).idle();Thread.sleep(10);boolean loading=org.robolectric.util.ReflectionHelpers.getField(ui,"loading");if(requests.get()>count&&!loading){System.out.println("REPLAY "+label+" "+order());return;}}throw new AssertionError("snapshot not rendered: "+label);}
 void texts(View view,StringBuilder text){if(view instanceof TextView)text.append(((TextView)view).getText());if(view instanceof ViewGroup)for(int i=0;i<((ViewGroup)view).getChildCount();i++)texts(((ViewGroup)view).getChildAt(i),text);}
 List<String> order(){List<String> order=new ArrayList<>();for(int i=0;i<chat.timeline.getChildCount();i++){StringBuilder text=new StringBuilder();texts(chat.timeline.getChildAt(i),text);for(String marker:new String[]{"STREAM-FIRST","STREAM-FOLLOWUP","STREAM-ANSWER","TOOL-FIRST","TOOL-FOLLOWUP","TOOL-ANSWER"})if(text.toString().contains(marker))order.add(marker);}return order;}
 Set<String> ids(String label,String marker)throws Exception{Set<String> ids=new LinkedHashSet<>();JSONArray rows=snapshot(label).getJSONArray("rows");for(int i=0;i<rows.length();i++){JSONObject r=rows.getJSONObject(i);if(r.optString("kind").equals("user")&&r.optString("body").contains(marker))ids.add(r.getString("key"));}return ids;}
 @Test public void queuedNextTurnUsesNativeOrderAndExplicitQueueCaption()throws Exception{
  apply("stream-before-first-byte");assertTrue(order().contains("STREAM-FOLLOWUP"));assertTrue(hasText(chat,"В очереди — после текущей задачи"));
  apply("stream-during-text");assertTrue(order().indexOf("STREAM-FOLLOWUP")<order().indexOf("STREAM-ANSWER"));
  apply("stream-after-final");assertTrue(order().indexOf("STREAM-ANSWER")<order().indexOf("STREAM-FOLLOWUP"));assertEquals(1,Collections.frequency(order(),"STREAM-FOLLOWUP"));assertEquals(ids("stream-during-text","STREAM-FOLLOWUP"),ids("stream-after-final","STREAM-FOLLOWUP"));
 }
 boolean hasText(View view,String value){StringBuilder b=new StringBuilder();texts(view,b);return b.toString().contains(value);}
 @Test public void absorbedInputsKeepTheirPlacesAndDistinctUuidsAfterColdReopen()throws Exception{
  apply("tool-before-completion");assertEquals(2,Collections.frequency(order(),"TOOL-FOLLOWUP"));
  apply("tool-after-final");assertEquals(2,Collections.frequency(order(),"TOOL-FOLLOWUP"));assertTrue(order().lastIndexOf("TOOL-FOLLOWUP")<order().indexOf("TOOL-ANSWER"));Set<String> keys=ids("tool-before-completion","TOOL-FOLLOWUP");assertEquals(2,keys.size());assertEquals(keys,ids("tool-after-final","TOOL-FOLLOWUP"));
  ui.close();ui=null;apply("cold-reopen");assertEquals(2,Collections.frequency(order(),"TOOL-FOLLOWUP"));assertTrue(order().lastIndexOf("TOOL-FOLLOWUP")<order().indexOf("TOOL-ANSWER"));assertEquals(keys,ids("cold-reopen","TOOL-FOLLOWUP"));JSONArray rows=snapshot("cold-reopen").getJSONArray("rows");for(int i=0;i<rows.length();i++)if(keys.contains(rows.getJSONObject(i).optString("key")))assertFalse(rows.getJSONObject(i).has("deliveryReceipt"));
 }
}
